1	/**
2	 * Animated "global reach" motif — a stylised network globe with pulsing edge
3	 * nodes and travelling data arcs. Pure SVG + scoped CSS keyframes, no assets.
4	 * Server-safe (renders a <style> tag with static markup).
5	 */
6	export function GlobalNetwork() {
7	  const nodes = [
8	    { cx: 90, cy: 120, d: "0s" },
9	    { cx: 250, cy: 70, d: "0.6s" },
10	    { cx: 420, cy: 110, d: "1.2s" },
11	    { cx: 150, cy: 250, d: "0.9s" },
12	    { cx: 330, cy: 260, d: "0.3s" },
13	    { cx: 470, cy: 230, d: "1.5s" },
14	  ];
15	  const arcs = [
16	    "M90 120 Q180 20 250 70",
17	    "M250 70 Q360 30 420 110",
18	    "M90 120 Q120 200 150 250",
19	    "M150 250 Q240 300 330 260",
20	    "M330 260 Q420 300 470 230",
21	    "M250 70 Q300 170 330 260",
22	  ];
23	
24	  return (
25	    <div className="relative mx-auto w-full max-w-xl">
26	      <div className="pointer-events-none absolute inset-0 rounded-full bg-gradient-to-br from-accent-blue/15 to-brand-500/15 blur-3xl" />
27	      <svg viewBox="0 0 540 340" className="relative w-full" role="img" aria-label="Global network reach">
28	        <defs>
29	          <radialGradient id="ng-globe" cx="50%" cy="40%" r="65%">
30	            <stop offset="0%" stopColor="#1a2540" stopOpacity="0.9" />
31	            <stop offset="100%" stopColor="#060a14" stopOpacity="0.2" />
32	          </radialGradient>
33	          <linearGradient id="ng-arc" x1="0" y1="0" x2="1" y2="0">
34	            <stop offset="0%" stopColor="#3b82f6" />
35	            <stop offset="100%" stopColor="#8a70fb" />
36	          </linearGradient>
37	        </defs>
38	
39	        {/* globe body */}
40	        <circle cx="270" cy="170" r="150" fill="url(#ng-globe)" stroke="rgba(255,255,255,0.06)" />
41	        {/* longitude / latitude lines */}
42	        <g stroke="rgba(138,112,251,0.22)" fill="none" strokeWidth="1">
43	          <ellipse cx="270" cy="170" rx="150" ry="60" />
44	          <ellipse cx="270" cy="170" rx="150" ry="110" />
45	          <ellipse cx="270" cy="170" rx="60" ry="150" />
46	          <ellipse cx="270" cy="170" rx="110" ry="150" />
47	          <line x1="120" y1="170" x2="420" y2="170" />
48	          <line x1="270" y1="20" x2="270" y2="320" />
49	        </g>
50	
51	        {/* travelling arcs */}
52	        <g fill="none" stroke="url(#ng-arc)" strokeWidth="1.6" strokeLinecap="round">
53	          {arcs.map((d, i) => (
54	            <path
55	              key={i}
56	              d={d}
57	              className="ng-arc"
58	              style={{ animationDelay: `${i * 0.5}s` }}
59	              strokeDasharray="6 210"
60	            />
61	          ))}
62	        </g>
