3	import Link from "next/link";
4	import { useRef, useState } from "react";
5	import { RunButton, ResultCard, KeyValue } from "./ui";
6	
7	type Sample = { ms: number };
8	
9	const SAMPLES = 15;
10	
11	function quality(avg: number): { label: string; tone: string } {
12	  if (avg < 40) return { label: "Excellent", tone: "text-emerald-300" };
13	  if (avg < 80) return { label: "Great", tone: "text-emerald-300" };
14	  if (avg < 150) return { label: "Good", tone: "text-amber-300" };
15	  return { label: "High", tone: "text-red-300" };
16	}
17	
18	export function LatencyTestTool() {
19	  const [running, setRunning] = useState(false);
20	  const [progress, setProgress] = useState(0);
21	  const [samples, setSamples] = useState<Sample[]>([]);
22	  const [done, setDone] = useState(false);
23	  const abort = useRef(false);
24	
25	  async function run() {
26	    setRunning(true);
27	    setDone(false);
28	    setSamples([]);
29	    setProgress(0);
30	    abort.current = false;
31	    const collected: Sample[] = [];
32	
33	    // One warm-up request so DNS/TLS/connection setup doesn't skew the first sample.
34	    try {
35	      await fetch(`/api/tools/ping?warmup=1`, { cache: "no-store" });
36	    } catch {
37	      /* ignore warm-up failure */
38	    }
39	
40	    for (let i = 0; i < SAMPLES; i++) {
41	      if (abort.current) break;
42	      const start = performance.now();
43	      try {
44	        const res = await fetch(`/api/tools/ping?n=${i}&_=${Date.now()}`, { cache: "no-store" });
45	        if (!res.ok) continue;
46	        await res.arrayBuffer();
47	        const ms = performance.now() - start;
48	        collected.push({ ms });
49	        setSamples([...collected]);
50	      } catch {
51	        /* skip failed sample */
52	      }
53	      setProgress(Math.round(((i + 1) / SAMPLES) * 100));
54	      await new Promise((r) => setTimeout(r, 120));
55	    }
56	
57	    setRunning(false);
58	    setDone(true);
59	  }
60	
61	  const values = samples.map((s) => s.ms);
62	  const avg = values.length ? values.reduce((a, b) => a + b, 0) / values.length : 0;
63	  const min = values.length ? Math.min(...values) : 0;
64	  const max = values.length ? Math.max(...values) : 0;
65	  // Jitter: mean absolute deviation between consecutive samples.
66	  let jitter = 0;
67	  if (values.length > 1) {
68	    let sum = 0;
69	    for (let i = 1; i < values.length; i++) sum += Math.abs(values[i] - values[i - 1]);
70	    jitter = sum / (values.length - 1);
71	  }
72	  const q = quality(avg);
73	
74	  return (
75	    <div className="space-y-5">
76	      <div className="flex flex-col items-start gap-3 sm:flex-row sm:items-center sm:justify-between">
77	        <p className="text-sm text-slate-400">
78	          Measures round-trip latency from your browser to the Nxeon edge over {SAMPLES} samples.
79	        </p>
80	        <RunButton loading={running} onClick={run}>
81	          {done ? "Run again" : "Start test"}
82	        </RunButton>
83	      </div>
84	
85	      {(running || done) && (
86	        <div className="h-2 w-full overflow-hidden rounded-full bg-white/[0.06]">
87	          <div
88	            className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500 transition-all duration-200"
89	            style={{ width: `${progress}%` }}
90	          />
91	        </div>
92	      )}
93	
94	      {values.length > 0 && (
95	        <ResultCard>
96	          <div className="mb-4 flex flex-wrap items-end gap-x-6 gap-y-2">
97	            <div>
98	              <p className="text-xs font-medium uppercase tracking-wide text-slate-500">Average latency</p>
99	              <p className="text-3xl font-bold text-white">
100	                {avg.toFixed(0)}
101	                <span className="ml-1 text-lg font-medium text-slate-400">ms</span>
102	              </p>
103	            </div>
104	            <p className={`text-sm font-semibold ${q.tone}`}>{q.label}</p>
105	          </div>
106	          <KeyValue
107	            rows={[
108	              ["Best", `${min.toFixed(0)} ms`],
109	              ["Worst", `${max.toFixed(0)} ms`],
110	              ["Jitter", `${jitter.toFixed(0)} ms`],
111	              ["Samples", `${values.length} / ${SAMPLES}`],
112	            ]}
113	          />
114	        </ResultCard>
115	      )}
116	
117	      <div className="rounded-xl border border-brand-500/20 bg-gradient-to-br from-brand-500/10 to-accent-blue/5 p-4">
118	        <p className="text-sm text-slate-300">
119	          This is the latency you'd get to a Nxeon VPS in our Singapore region. Numbers depend on your
120	          own connection and distance to Singapore — {" "}
121	          <Link href="/vps" className="font-semibold text-brand-300 hover:text-brand-200">
122	            deploy a low-latency NVMe VPS
123	          </Link>{" "}
124	          and feel it for yourself.
125	        </p>
126	        <p className="mt-2 text-xs text-slate-500">
127	          We currently serve from a single Singapore data center, so this reflects APAC latency
128	          honestly — we won't pretend to have edges we don't.
129	        </p>
130	      </div>
131	    </div>
132	  );
133	}
