"use client";

import { useEffect, useRef, useState } from "react";

/**
 * Scroll-triggered numeric count-up, used by the Singapore page's proof strip.
 * Animates from 0 to `value` once the element enters the viewport; renders the
 * final value immediately for `prefers-reduced-motion` or when IntersectionObserver
 * is unavailable (SSR-safe fallback).
 */
export function CountUp({
  value,
  duration = 1100,
  decimals = 0,
  suffix = "",
  prefix = "",
  className = "",
}: {
  value: number;
  duration?: number;
  decimals?: number;
  suffix?: string;
  prefix?: string;
  className?: string;
}) {
  const ref = useRef<HTMLSpanElement | null>(null);
  const [display, setDisplay] = useState(0);
  const [done, setDone] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const reduce = typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (reduce || typeof IntersectionObserver === "undefined") {
      setDisplay(value);
      setDone(true);
      return;
    }

    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          if (!e.isIntersecting) continue;
          io.disconnect();
          const start = performance.now();
          const tick = (now: number) => {
            const t = Math.min(1, (now - start) / duration);
            // ease-out cubic
            const eased = 1 - Math.pow(1 - t, 3);
            setDisplay(value * eased);
            if (t < 1) requestAnimationFrame(tick);
            else {
              setDisplay(value);
              setDone(true);
            }
          };
          requestAnimationFrame(tick);
        }
      },
      { threshold: 0.4 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [value, duration]);

  return (
    <span ref={ref} className={className}>
      {prefix}
      {done ? value.toFixed(decimals) : display.toFixed(decimals)}
      {suffix}
    </span>
  );
}

/**
 * Singapore radar — a bespoke APAC-reach visualization for the Singapore VPS
 * landing page ONLY. Deliberately a different motion language from the shared
 * templates' dotted-world-map + travelling-arc look (NetworkMap.tsx,
 * GlobalNetwork.tsx, used by the other 13 use-case/location pages): here a single
 * rotating radar sweep, centred on one honest datacenter, "pings" each city as it
 * passes — the metaphor is "one real place, scanning outward" rather than a global
 * mesh, which matches the honesty message (we run ONE Singapore DC, not a fake
 * multi-region claim).
 *
 * Cities are placed at illustrative angles (for visual balance, not literal
 * bearings) but PRESERVE real relative distance ordering from Singapore — nearest
 * ring is genuinely nearest, no fabricated numbers are printed on the graphic.
 * Pure SVG + scoped CSS keyframes, deterministic, SSR-safe, no client JS.
 */

const CX = 320;
const CY = 320;
const RINGS = [86, 156, 226];
const SWEEP_SECONDS = 7;

type City = { name: string; ring: 0 | 1 | 2; angle: number; note: string };

// Angle = degrees clockwise from due north (12 o'clock). Distances are
// illustrative but the ring assignment reflects genuine relative proximity to
// Singapore (SEA neighbours nearest, extended APAC furthest).
const CITIES: City[] = [
  { name: "Kuala Lumpur", ring: 0, angle: 330, note: "SEA" },
  { name: "Jakarta", ring: 0, angle: 195, note: "SEA" },
  { name: "Ho Chi Minh City", ring: 1, angle: 25, note: "SEA" },
  { name: "Bangkok", ring: 1, angle: 300, note: "SEA" },
  { name: "Manila", ring: 1, angle: 55, note: "SEA" },
  { name: "Hong Kong", ring: 2, angle: 40, note: "East Asia" },
  { name: "Mumbai", ring: 2, angle: 280, note: "South Asia" },
  { name: "Tokyo", ring: 2, angle: 60, note: "East Asia" },
  { name: "Sydney", ring: 2, angle: 150, note: "Oceania" },
];

const RING_LABEL = ["SEA neighbors", "Regional APAC", "Extended reach"];

function pt(angleDeg: number, r: number) {
  const rad = (angleDeg * Math.PI) / 180;
  return { x: CX + r * Math.sin(rad), y: CY - r * Math.cos(rad) };
}

export function RadarMap() {
  return (
    <div className="relative overflow-hidden rounded-[28px] border border-white/[0.08] bg-navy-950/70">
      <style>{`
        @keyframes sg-sweep-spin { to { transform: rotate(360deg); } }
        @keyframes sg-ring-breathe { 0%, 100% { opacity: 0.22; } 50% { opacity: 0.5; } }
        @keyframes sg-ping-flash {
          0%, 92%, 100% { opacity: 0; transform: scale(1); }
          2% { opacity: 1; transform: scale(1); }
          14% { opacity: 0; transform: scale(2.6); }
        }
        @keyframes sg-core-pulse {
          0%, 100% { box-shadow: 0 0 0 0 rgba(34,211,238,0.55); }
          50% { box-shadow: 0 0 0 14px rgba(34,211,238,0); }
        }
        .sg-sweep-wedge {
          animation: sg-sweep-spin ${SWEEP_SECONDS}s linear infinite;
          transform-origin: ${CX}px ${CY}px;
        }
        .sg-ring { animation: sg-ring-breathe 4s ease-in-out infinite; }
        .sg-ping { animation: sg-ping-flash ${SWEEP_SECONDS}s linear infinite; transform-origin: center; }
        @media (prefers-reduced-motion: reduce) {
          .sg-sweep-wedge { animation: none; opacity: 0.35; }
          .sg-ring { animation: none; opacity: 0.32; }
          .sg-ping { animation: none; opacity: 0.85; }
        }
      `}</style>

      {/* header, matches the console-panel framing convention used elsewhere on the site */}
      <div className="flex items-center justify-between border-b border-white/[0.06] px-4 py-2.5 font-mono text-[11px]">
        <span className="flex items-center gap-2 text-slate-500">
          <span className="h-1.5 w-1.5 rounded-full bg-emerald-400" /> nxeon · singapore datacenter
        </span>
        <span className="text-slate-500">1 region · no fake multi-region claims</span>
      </div>

      <div className="relative">
        <div aria-hidden className="pointer-events-none absolute inset-0 bg-[radial-gradient(ellipse_at_center,rgba(111,71,245,0.12),transparent_65%)]" />
        <svg viewBox="0 0 640 640" className="relative block w-full" role="img" aria-label="Radar-style diagram of Singapore's reach across Southeast Asia, South Asia, East Asia and Oceania">
          <defs>
            <radialGradient id="sg-core" cx="50%" cy="50%" r="50%">
              <stop offset="0%" stopColor="#22d3ee" />
              <stop offset="100%" stopColor="#6f47f5" />
            </radialGradient>
            <linearGradient id="sg-wedge" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#22d3ee" stopOpacity="0.35" />
              <stop offset="100%" stopColor="#22d3ee" stopOpacity="0" />
            </linearGradient>
          </defs>

          {/* rings */}
          {RINGS.map((r, i) => (
            <circle key={r} className="sg-ring" cx={CX} cy={CY} r={r} fill="none" stroke="#8a70fb" strokeWidth="1" strokeDasharray="2 5" style={{ animationDelay: `${i * 0.4}s` }} />
          ))}

          {/* ring labels */}
          {RINGS.map((r, i) => (
            <text key={`l-${r}`} x={CX + 6} y={CY - r + 13} fontFamily="ui-monospace,monospace" fontSize="9.5" fill="#64748b">
              {RING_LABEL[i]}
            </text>
          ))}

          {/* rotating sweep wedge (radar cone) */}
          <g className="sg-sweep-wedge">
            <path d={`M${CX},${CY} L${CX},${CY - RINGS[2]} A${RINGS[2]},${RINGS[2]} 0 0 1 ${pt(34, RINGS[2]).x},${pt(34, RINGS[2]).y} Z`} fill="url(#sg-wedge)" />
            <line x1={CX} y1={CY} x2={CX} y2={CY - RINGS[2]} stroke="#22d3ee" strokeWidth="1.4" opacity="0.8" />
          </g>

          {/* city nodes + ping flash timed to the sweep passing their angle */}
          {CITIES.map((c) => {
            const r = RINGS[c.ring];
            const { x, y } = pt(c.angle, r);
            const delay = -((c.angle / 360) * SWEEP_SECONDS) + "s";
            const labelRight = c.angle > 180;
            return (
              <g key={c.name}>
                <circle className="sg-ping" cx={x} cy={y} r="5" fill="none" stroke="#22d3ee" strokeWidth="1.6" style={{ animationDelay: delay }} />
                <circle cx={x} cy={y} r="3" fill="#e0e7ff" />
                <g transform={`translate(${x + (labelRight ? 9 : -9)}, ${y - 5})`} textAnchor={labelRight ? "start" : "end"}>
                  <text fontFamily="var(--font-sans)" fontSize="11" fontWeight="600" fill="#cbd5e1">
                    {c.name}
                  </text>
                  <text y="12" fontFamily="ui-monospace,monospace" fontSize="8.5" fill="#64748b">
                    {c.note}
                  </text>
                </g>
              </g>
            );
          })}

          {/* Singapore core */}
          <g>
            <circle cx={CX} cy={CY} r="9" fill="url(#sg-core)" />
            <circle cx={CX} cy={CY} r="9" fill="none" style={{ animation: "sg-core-pulse 2.4s ease-out infinite" }} />
            <text x={CX} y={CY + 26} textAnchor="middle" fontFamily="ui-monospace,monospace" fontSize="10.5" fontWeight="600" fill="#e0e7ff">
              SINGAPORE
            </text>
          </g>
        </svg>
      </div>
    </div>
  );
}

