const { AbsoluteFill, useCurrentFrame, useVideoConfig } = window.Remotion;

/* ============================================================================
   "Convergence" — ambient blend-overlay loop for nxeon.cloud/singapore-vps-hosting
   PURE BLACK canvas by design: this composites onto the live page via CSS
   mix-blend-mode: screen/lighten, so #000 pixels must vanish and only the glow
   should read. 8 independent light trails drift in from the frame edges and
   curve toward one bright cyan point near center — "all APAC traffic
   converging on one real, honest datacenter" — plus two large soft
   out-of-focus glow blobs drifting slowly behind them for depth.

   SEAMLESS LOOP, by construction: every phase function below is driven by
   frame/DURATION with an INTEGER cycle count, so the value at frame=DURATION
   is bit-identical to frame=0. No easing/ease-out curves that "arrive" and
   stop — everything is a periodic sine/cosine or a pathLength-normalized dash
   offset shifted by an integer multiple of its own pattern length.
   ========================================================================= */

const CYAN = "#22d3ee";
const BLUE = "#3b82f6";
const BRAND_400 = "#8a70fb";
const BRAND_500 = "#6f47f5";

const DURATION = 150; // 5s @ 30fps — matches the scene's authored duration

// Each trail: a fixed bezier from an edge point toward the convergence point,
// a color, a dash pattern (pathLength-normalized to 100 so math never needs
// the real geometry), an integer loop-speed (how many times its dash pattern
// cycles over DURATION — keeps the loop seamless), a phase offset so trails
// don't all flow in lockstep, and an integer opacity-pulse cycle count.
const CONVERGE = { x: 66, y: 46 }; // percent — the bright point everything flows toward
const TRAILS = [
  { from: { x: -6, y: 14 }, via: { x: 30, y: 8 }, color: CYAN, speed: 2, phase: 0, pulse: 1, width: 0.55 },
  { from: { x: 8, y: -6 }, via: { x: 34, y: 20 }, color: BRAND_400, speed: 1, phase: 18, pulse: 1, width: 0.4 },
  { from: { x: -8, y: 62 }, via: { x: 20, y: 52 }, color: BLUE, speed: 3, phase: 40, pulse: 2, width: 0.5 },
  { from: { x: 40, y: 104 }, via: { x: 48, y: 76 }, color: CYAN, speed: 1, phase: 62, pulse: 1, width: 0.35 },
  { from: { x: 106, y: 30 }, via: { x: 84, y: 34 }, color: BRAND_500, speed: 2, phase: 84, pulse: 1, width: 0.55 },
  { from: { x: 96, y: 90 }, via: { x: 80, y: 66 }, color: CYAN, speed: 1, phase: 26, pulse: 2, width: 0.4 },
  { from: { x: -10, y: 92 }, via: { x: 18, y: 76 }, color: BRAND_400, speed: 3, phase: 104, pulse: 1, width: 0.35 },
  { from: { x: 60, y: -8 }, via: { x: 62, y: 18 }, color: BLUE, speed: 2, phase: 130, pulse: 1, width: 0.45 },
];

function pct(n) {
  return n + "%";
}

/** Quadratic bezier path in percent-space, drawn into a 0..100 viewBox. */
function bezierPath(from, via, to) {
  return "M " + from.x + "," + from.y + " Q " + via.x + "," + via.y + " " + to.x + "," + to.y;
}

/** Integer-cycle sine, so value(0) === value(DURATION) exactly. */
function loopSin(frame, cycles, phaseFrames) {
  return Math.sin((2 * Math.PI * cycles * (frame + phaseFrames)) / DURATION);
}

function GlowBlob({ cx, cy, size, color, cycles, phase, driftPct }) {
  const frame = useCurrentFrame();
  const dx = loopSin(frame, cycles, phase) * driftPct;
  const dy = loopSin(frame, cycles, phase + DURATION / 4) * driftPct * 0.6;
  return (
    <div
      style={{
        position: "absolute",
        left: pct(cx + dx),
        top: pct(cy + dy),
        width: size,
        height: size,
        marginLeft: -size / 2,
        marginTop: -size / 2,
        borderRadius: "50%",
        background: color,
        filter: "blur(90px)",
        opacity: 0.5,
      }}
    />
  );
}

function Trail({ from, via, color, speed, phase, pulse, width }) {
  const frame = useCurrentFrame();
  // pathLength=100 lets every trail share the same dash math regardless of
  // its real on-screen length.
  const dashLen = 22;
  const gapLen = 78;
  // Shift the dash pattern by an INTEGER multiple of the 100-unit pattern
  // over the full duration -> frame 0 and frame DURATION render identically.
  const shift = ((frame + phase) / DURATION) * 100 * speed;
  const offset = -(shift % 100);
  const opacity = 0.28 + 0.34 * (0.5 + 0.5 * loopSin(frame, pulse, phase));

  return (
    <path
      d={bezierPath(from, via, CONVERGE)}
      pathLength={100}
      fill="none"
      stroke={color}
      strokeWidth={width}
      strokeLinecap="round"
      strokeDasharray={dashLen + " " + gapLen}
      strokeDashoffset={offset}
      opacity={opacity}
      style={{ filter: "drop-shadow(0 0 2.2px " + color + ") drop-shadow(0 0 6px " + color + ")" }}
    />
  );
}

export default function Scene_singapore_convergence() {
  const frame = useCurrentFrame();

  // The convergence point itself breathes gently — the "one real datacenter".
  const coreScale = 1 + 0.16 * (0.5 + 0.5 * loopSin(frame, 5, 0));
  const coreOpacity = 0.75 + 0.25 * (0.5 + 0.5 * loopSin(frame, 5, DURATION / 10));

  return (
    <AbsoluteFill style={{ background: "#000000", overflow: "hidden" }}>
      <GlowBlob cx={30} cy={70} size={620} color={BRAND_500} cycles={1} phase={0} driftPct={5} />
      <GlowBlob cx={72} cy={28} size={520} color={BLUE} cycles={1} phase={DURATION / 3} driftPct={4} />

      <svg viewBox="0 0 100 56.25" preserveAspectRatio="xMidYMid slice" style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }}>
        {TRAILS.map((t, i) => (
          <Trail key={i} {...t} />
        ))}

        {/* convergence node */}
        <circle cx={CONVERGE.x} cy={CONVERGE.y} r={0.55 * coreScale} fill={CYAN} opacity={coreOpacity} style={{ filter: "drop-shadow(0 0 3px " + CYAN + ") drop-shadow(0 0 10px " + CYAN + ")" }} />
        <circle cx={CONVERGE.x} cy={CONVERGE.y} r={1.6 * coreScale} fill="none" stroke={CYAN} strokeWidth={0.12} opacity={coreOpacity * 0.5} />
      </svg>
    </AbsoluteFill>
  );
}

