"use client";

import { useEffect, useRef, useState } from "react";

/**
 * A compact, auto-running LIVE latency reading to Nxeon's Singapore edge —
 * the strongest possible APAC proof, and it's real (hits the same
 * /api/tools/ping endpoint as /tools/latency-test), not a fabricated claim.
 * Runs a handful of samples automatically on mount so it's the first thing a
 * visitor sees resolve in the hero, with a manual re-run button after.
 */
const SAMPLES = 8;

function quality(avg: number): { label: string; tone: string } {
  if (avg < 40) return { label: "Excellent", tone: "text-emerald-300" };
  if (avg < 80) return { label: "Great", tone: "text-emerald-300" };
  if (avg < 150) return { label: "Good", tone: "text-amber-300" };
  return { label: "Fair", tone: "text-amber-300" };
}

export function LiveLatencyWidget() {
  const [samples, setSamples] = useState<number[]>([]);
  const [running, setRunning] = useState(false);
  const [done, setDone] = useState(false);
  const ranOnce = useRef(false);

  async function run() {
    setRunning(true);
    setDone(false);
    setSamples([]);
    const collected: number[] = [];
    try {
      await fetch(`/api/tools/ping?warmup=1`, { cache: "no-store" });
    } catch {
      /* ignore warm-up failure */
    }
    for (let i = 0; i < SAMPLES; i++) {
      const start = performance.now();
      try {
        const res = await fetch(`/api/tools/ping?n=${i}&_=${Date.now()}`, { cache: "no-store" });
        if (res.ok) {
          await res.arrayBuffer();
          collected.push(performance.now() - start);
          setSamples([...collected]);
        }
      } catch {
        /* skip a failed sample */
      }
      await new Promise((r) => setTimeout(r, 90));
    }
    setRunning(false);
    setDone(true);
  }

  useEffect(() => {
    if (ranOnce.current) return;
    ranOnce.current = true;
    run();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const avg = samples.length ? samples.reduce((a, b) => a + b, 0) / samples.length : 0;
  const q = quality(avg);
  const bars = 8;

  return (
    <div className="rounded-2xl border border-white/[0.08] bg-navy-950/70 p-4 font-mono backdrop-blur-md">
      <div className="flex items-center justify-between text-[11px] text-slate-500">
        <span className="flex items-center gap-1.5">
          <span className={`h-1.5 w-1.5 rounded-full ${running ? "bg-amber-400" : "bg-emerald-400"}`} />
          live · your browser → singapore edge
        </span>
        <button
          type="button"
          onClick={run}
          disabled={running}
          className="text-brand-300 hover:text-brand-200 disabled:opacity-40"
        >
          {running ? "measuring…" : "re-test"}
        </button>
      </div>

      <div className="mt-2.5 flex items-end gap-3">
        <div className="flex items-baseline gap-1">
          <span className="text-4xl font-bold tabular-nums tracking-tight text-white">
            {samples.length ? Math.round(avg) : "—"}
          </span>
          <span className="text-sm text-slate-400">ms</span>
        </div>
        {done && <span className={`pb-1 text-xs font-semibold ${q.tone}`}>{q.label}</span>}
      </div>

      {/* live sparkline of raw samples as they arrive */}
      <div className="mt-3 flex h-8 items-end gap-[3px]">
        {Array.from({ length: bars }).map((_, i) => {
          const s = samples[i];
          const max = Math.max(60, ...samples);
          const h = s ? Math.max(8, (s / max) * 100) : 6;
          return (
            <div
              key={i}
              className={`flex-1 rounded-sm transition-all duration-300 ${s ? "bg-gradient-to-t from-accent-blue to-accent-cyan" : "bg-white/[0.06]"}`}
              style={{ height: `${h}%` }}
            />
          );
        })}
      </div>
      <p className="mt-3 text-[11px] leading-relaxed text-slate-500">
        Measured this instant, from your connection — not a marketing average. One Singapore datacenter, honestly.
      </p>
    </div>
  );
}

import { CountUp } from "./CountUp";

/**
 * A compact, scannable real-number strip directly under the hero — the
 * "surfaced early" proof the shared template buries after a paragraph of
 * prose and a feature grid. Every figure here is a real, sitewide-consistent
 * platform fact (same numbers used on the homepage / other pages), not
 * page-specific marketing math.
 */
const STATS: { value: number; decimals?: number; prefix?: string; suffix: string; label: string }[] = [
  { value: 99.9, decimals: 1, suffix: "%", label: "Uptime SLA, credited" },
  { value: 47, suffix: "s", label: "Median deploy time" },
  { value: 8.88, decimals: 2, prefix: "$", suffix: "/mo", label: "Starting price, Singapore" },
  { value: 1, suffix: " region", label: "Real datacenter, no fake edges" },
];

export function ProofStrip() {
  return (
    <section className="border-b border-white/[0.05] bg-navy-900/40">
      <div className="rail grid grid-cols-2 divide-x divide-white/[0.06] sm:grid-cols-4 sm:divide-y-0">
        {STATS.map((s, i) => (
          <div key={s.label} className={`px-4 py-7 text-center sm:px-6 ${i >= 2 ? "border-t border-white/[0.06] sm:border-t-0" : ""}`}>
            <div className="text-3xl font-bold tabular-nums tracking-tight text-white sm:text-4xl">
              <CountUp value={s.value} decimals={s.decimals ?? 0} prefix={s.prefix} suffix={s.suffix} />
            </div>
            <p className="mt-1.5 text-xs text-slate-500 sm:text-sm">{s.label}</p>
          </div>
        ))}
      </div>
    </section>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { termPriceCents, ANNUAL_TERM_MONTHS } from "@/lib/billing-terms";
import { useDisplayMoney } from "@/components/currency/CurrencyContext";
import { planTip, planAudience } from "@/components/marketing/planTips";
import { IconCheck, IconNvme, IconShield, IconBackup, IconGlobe } from "@/components/marketing/icons";

export type SgPlan = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
  storageTier: string;
};

const INCLUDED = [
  { icon: IconNvme, label: "Enterprise NVMe on self-healing ZFS" },
  { icon: IconGlobe, label: "Dedicated IPv4 on every plan" },
  { icon: IconShield, label: "Always-on DDoS protection + firewall" },
  { icon: IconBackup, label: "Daily backups + instant snapshots" },
];

/**
 * Bespoke pricing presentation for the Singapore page — same live plan data,
 * same money/term math as the shared <PricingGrid>, but a different shape:
 * the shared feature checklist is stated ONCE (it's identical across plans),
 * and each plan card is a compact spec table instead of a repeated bullet
 * list. Shorter, easier to scan side-by-side, and visually distinct from the
 * card style used on every other VPS/location page.
 */
export function SingaporePricing({ plans, annualPct }: { plans: SgPlan[]; annualPct: number }) {
  const money = useDisplayMoney();
  const annualAvailable = annualPct > 0;
  const [annual, setAnnual] = useState(true);
  const showAnnual = annual && annualAvailable;
  const popularIdx = plans.length ? Math.floor((plans.length - 1) / 2) : -1;

  if (plans.length === 0) {
    return <div className="card text-center text-slate-400">Plans are being provisioned. Check back shortly.</div>;
  }

  const fromCents = Math.min(...plans.map((p) => p.priceCents));
  const toCents = Math.max(...plans.map((p) => p.priceCents));

  return (
    <div>
      <div className="mx-auto mb-9 grid max-w-4xl gap-x-6 gap-y-3 sm:grid-cols-2">
        {INCLUDED.map((f) => (
          <div key={f.label} className="flex items-center gap-3 text-sm text-slate-300">
            <span className="flex h-8 w-8 flex-none items-center justify-center rounded-lg border border-white/[0.08] bg-white/[0.03] text-cyan-300">
              <f.icon size={16} />
            </span>
            {f.label}
          </div>
        ))}
      </div>

      {annualAvailable && (
        <div className="mb-8 flex justify-center">
          <div className="inline-flex items-center rounded-full border border-white/10 bg-navy-900/70 p-1">
            <button
              type="button"
              aria-pressed={!annual}
              onClick={() => setAnnual(false)}
              className={`rounded-full px-4 py-1.5 text-sm font-semibold transition-colors ${!annual ? "bg-white/10 text-white" : "text-slate-400 hover:text-white"}`}
            >
              Monthly
            </button>
            <button
              type="button"
              aria-pressed={annual}
              onClick={() => setAnnual(true)}
              className={`flex items-center gap-2 rounded-full px-4 py-1.5 text-sm font-semibold transition-colors ${annual ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white" : "text-slate-400 hover:text-white"}`}
            >
              Annual
              <span className={`rounded-full px-1.5 py-0.5 text-[10px] font-bold ${annual ? "bg-white/20 text-white" : "bg-emerald-500/15 text-emerald-300"}`}>
                –{annualPct}%
              </span>
            </button>
          </div>
        </div>
      )}

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {plans.map((p, i) => {
          const popular = i === popularIdx;
          const annualPerMo = annualAvailable
            ? Math.round(termPriceCents(p.priceCents, ANNUAL_TERM_MONTHS, annualPct) / ANNUAL_TERM_MONTHS)
            : 0;
          const bigCents = showAnnual ? annualPerMo : p.priceCents;
          const rows: [string, string][] = [
            ["vCPU", `${p.cpuCores} core${p.cpuCores > 1 ? "s" : ""}`],
            ["RAM", `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB`],
            ["Disk", `${p.diskGB} GB ${p.storageTier === "hdd" ? "HDD" : "NVMe"}`],
            ["Bandwidth", `${p.bandwidthTB} TB`],
          ];
          return (
            <div
              key={p.id}
              className={`relative flex flex-col rounded-2xl border p-5 transition-all duration-300 hover:-translate-y-1 ${
                popular ? "border-cyan-400/40 bg-navy-850/80" : "border-white/[0.07] bg-navy-900/60 hover:border-cyan-400/25"
              }`}
              style={popular ? { boxShadow: "0 0 44px -14px rgba(34,211,238,0.35)" } : undefined}
            >
              {popular && (
                <span className="absolute -top-3 left-1/2 -translate-x-1/2 rounded-full bg-gradient-to-r from-accent-cyan to-brand-500 px-3 py-1 text-[10px] font-semibold uppercase tracking-wider text-navy-950">
                  Best for most APAC sites
                </span>
              )}
              <h3 className="text-sm font-semibold uppercase tracking-wide text-slate-400">{p.name}</h3>
              <div className="mt-1.5 flex items-baseline gap-1">
                <span className="text-3xl font-bold tabular-nums tracking-tight text-white">{money(bigCents)}</span>
                <span className="text-sm text-slate-500">/mo</span>
              </div>
              <p className="mt-1 text-[11px] text-slate-500">
                {showAnnual ? `billed yearly, was ${money(p.priceCents)}/mo` : annualAvailable ? `or ${money(annualPerMo)}/mo annually` : "billed monthly"}
              </p>

              <dl className="mt-4 space-y-1.5 border-t border-white/[0.06] pt-4 text-[13px]">
                {rows.map(([k, v]) => (
                  <div key={k} className="flex items-center justify-between">
                    <dt className="text-slate-500">{k}</dt>
                    <dd className="font-medium text-slate-200">{v}</dd>
                  </div>
                ))}
              </dl>

              <p className="mt-4 text-[11px] leading-snug text-slate-500">
                <span className="font-semibold text-slate-300">{planAudience(p)}:</span> {planTip(p)}
              </p>

              <Link href="/register" className={`mt-5 w-full ${popular ? "btn-deploy" : "btn-secondary"}`}>
                Deploy now
                <IconCheck size={0} className="hidden" />
              </Link>
            </div>
          );
        })}
      </div>

      <p className="mt-6 text-center text-sm text-slate-500">
        From <span className="font-semibold text-slate-300">{money(fromCents)}</span> to{" "}
        <span className="font-semibold text-slate-300">{money(toCents)}/mo</span> — every tier, same Singapore
        datacenter, same full root access.
      </p>
    </div>
  );
}

