/**
 * A bespoke sticky bottom CTA for the Singapore page only — appears once the
 * visitor scrolls past the hero (tracked via IntersectionObserver on the
 * hero's #sg-hero-top sentinel), rather than being visible from scroll 0.
 */
export function StickyDeployBar() {
  const [show, setShow] = useState(false);

  useEffect(() => {
    const hero = document.getElementById("sg-hero-top");
    if (!hero || typeof IntersectionObserver === "undefined") return;
    const io = new IntersectionObserver(([entry]) => setShow(!entry.isIntersecting), { threshold: 0 });
    io.observe(hero);
    return () => io.disconnect();
  }, []);

  return (
    <div
      className={`fixed inset-x-0 bottom-0 z-40 border-t border-white/[0.08] bg-navy-950/90 backdrop-blur-md transition-transform duration-300 ease-out motion-reduce:transition-none ${
