/**
 * Bespoke page — the pilot for a fully custom marketing identity, distinct
 * from the shared <UseCaseLanding> template that the other 13 VPS use-case /
 * location pages still use. Every component this page renders lives in
 * components/marketing/singapore/ and is used ONLY here; nothing shared was
 * modified, so those 13 pages are unaffected (verified via
 * `grep -rl "UseCaseLanding" "app/(marketing)"`).
 */
export default async function SingaporeVpsHostingPage() {
  const [plans, annualPct] = await Promise.all([
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    annualDiscountPct(),
  ]);

  return (
    <>
      <FaqJsonLd items={FAQ} />
      {plans.length > 0 && <ProductJsonLd plans={plans} />}

      <SingaporeHero />
      <ProofStrip />

      <section id="sg-pricing" className="py-20 sm:py-24">
        <div className="rail">
          <div className="mx-auto max-w-2xl text-center">
            <span className="eyebrow">Plans</span>
            <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl">
              Real prices, no bait-and-switch region tax
            </h2>
            <p className="mt-3 text-slate-400">
              The same catalogue price everywhere else — Singapore isn&apos;t a premium tier.
            </p>
          </div>
          <div className="mt-10">
            <SingaporePricing plans={plans} annualPct={annualPct} />
          </div>
        </div>
      </section>

      <ApacReach />
      <ObjectionGrid />
      <DeploySteps steps={STEPS} />
      <SingaporeFaq faq={FAQ} />

      <section className="pb-4">
        <div className="rail flex flex-wrap items-center justify-center gap-2">
          <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
          {RELATED.map((r) => (
            <Link
              key={r.href}
              href={r.href}
              className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
            >
              {r.label}
            </Link>
          ))}
        </div>
      </section>

      <SingaporeCta />
      <StickyDeployBar />
    </>
  );
}

